import { request, PERSONAL_DRIVE_BASE_URL } from './http';

export function listFiles(parentId = 0) {
  return request(PERSONAL_DRIVE_BASE_URL, `/api/drive/list?parent_id=${parentId}`, {
    auth: true,
  });
}

export function getPath(dirId = 0) {
  return request(PERSONAL_DRIVE_BASE_URL, `/api/drive/path?dir_id=${dirId}`, {
    auth: true,
  });
}

export function checkNameConflict(parentId, name) {
  const params = new URLSearchParams({
    parent_id: parentId,
    name,
  });

  return request(PERSONAL_DRIVE_BASE_URL, `/api/drive/check_name?${params.toString()}`, {
    auth: true,
  });
}

export function uploadFile(parentId, file, options = {}) {
  const formData = new FormData();
  formData.append('parent_id', parentId);
  formData.append('file', file);
  if (options.targetName) formData.append('target_name', options.targetName);
  if (options.overwrite) formData.append('overwrite', 'true');

  return request(PERSONAL_DRIVE_BASE_URL, '/api/drive/upload', {
    method: 'POST',
    body: formData,
    auth: true,
  });
}

export function uploadFiles(parentId, files) {
  const formData = new FormData();
  formData.append('parent_id', parentId);
  files.forEach((file) => {
    formData.append('files', file);
  });

  return request(PERSONAL_DRIVE_BASE_URL, '/api/drive/batch_upload', {
    method: 'POST',
    body: formData,
    auth: true,
  });
}

export function createFolder(parentId, folderName) {
  return request(
    PERSONAL_DRIVE_BASE_URL,
    `/api/drive/new_folder/${parentId}/${encodeURIComponent(folderName)}`,
    {
      method: 'POST',
      auth: true,
    },
  );
}

export function renameItem(itemId, newName) {
  return request(PERSONAL_DRIVE_BASE_URL, '/api/drive/rename', {
    method: 'POST',
    body: {
      item_id: itemId,
      new_name: newName,
    },
    auth: true,
  });
}

export function deleteItem(itemId) {
  return request(PERSONAL_DRIVE_BASE_URL, `/api/drive/delete/${itemId}`, {
    method: 'DELETE',
    auth: true,
  });
}

export function downloadFile(itemId, onDownloadProgress) {
  return request(PERSONAL_DRIVE_BASE_URL, `/api/drive/download/${itemId}`, {
    auth: true,
    responseType: 'blob',
    onDownloadProgress,
  });
}
