export function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result).split(',')[1] || '');
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

export function createDefaultAvatar(username) {
  const canvas = document.createElement('canvas');
  canvas.width = 160;
  canvas.height = 160;

  const context = canvas.getContext('2d');
  const colors = ['#2563eb', '#059669', '#dc2626', '#7c3aed', '#d97706'];
  const index = username
    .split('')
    .reduce((sum, char) => sum + char.charCodeAt(0), 0) % colors.length;

  context.fillStyle = colors[index];
  context.fillRect(0, 0, canvas.width, canvas.height);
  context.fillStyle = '#ffffff';
  context.font = '700 72px Arial';
  context.textAlign = 'center';
  context.textBaseline = 'middle';
  context.fillText((username || 'U').slice(0, 1).toUpperCase(), 80, 84);

  return canvas.toDataURL('image/png').split(',')[1];
}
