<template>
  <AuthPanel v-if="!session" @authenticated="handleAuthenticated" />

  <div v-else class="app-layout">
    <AppSidebar
      :active="activeView"
      :session="session"
      @change="activeView = $event"
      @logout="logout"
    />

    <main class="app-main">
      <UserProfile v-if="activeView === 'profile'" :session="session" />
      <PersonalDrive v-else-if="activeView === 'drive'" />
      <CloudClipboard v-else />
    </main>
  </div>
</template>

<script>
import AppSidebar from '@/components/AppSidebar.vue';
import AuthPanel from '@/components/AuthPanel.vue';
import CloudClipboard from '@/views/CloudClipboard.vue';
import PersonalDrive from '@/views/PersonalDrive.vue';
import UserProfile from '@/views/UserProfile.vue';
import { clearSession, getSession } from '@/utils/session';
import { getMe } from '@/api/userInfo';

export default {
  name: 'App',
  components: {
    AppSidebar,
    AuthPanel,
    CloudClipboard,
    PersonalDrive,
    UserProfile,
  },
  data() {
    return {
      activeView: 'profile',
      session: getSession(),
    };
  },
  mounted() {
    this.validateSession();
  },
  methods: {
    async validateSession() {
      if (!this.session || !this.session.access_token) return;

      try {
        const data = await getMe();
        this.session = {
          ...this.session,
          username: data.username,
          avatar_url: data.avatar_url,
        };
      } catch (error) {
        clearSession();
        this.session = null;
      }
    },
    handleAuthenticated(session) {
      this.session = session;
      this.activeView = 'profile';
    },
    logout() {
      clearSession();
      this.session = null;
      this.activeView = 'profile';
    },
  },
};
</script>

<style scoped>
.app-layout {
  min-height: 100vh;
  display: flex;
  background: #f4f7fb;
}

.app-main {
  flex: 1;
  min-width: 0;
}

@media (max-width: 860px) {
  .app-layout {
    display: block;
  }
}
</style>
