<template>
  <section class="view-shell">
    <header class="view-header">
      <div>
        <h2>云端剪切板</h2>
        <p>同步文本剪切板内容，在桌面端、Android 和网页端之间流转。</p>
      </div>
      <div class="toolbar">
        <el-button icon="el-icon-refresh" :loading="loading" @click="refresh">刷新云端</el-button>
      </div>
    </header>

    <div class="clipboard-layout">
      <section class="clipboard-compose">
        <div class="section-title">
          <h3>同步新内容</h3>
          <span>当前服务仅支持文本</span>
        </div>

        <el-input
          v-model="draft"
          type="textarea"
          :rows="8"
          placeholder="输入文本，或点击读取剪切板后同步到云端"
        ></el-input>

        <div class="compose-actions">
          <el-button icon="el-icon-document-copy" @click="readClipboard">
            读取剪切板
          </el-button>
          <el-button type="primary" icon="el-icon-upload2" :loading="syncing" @click="syncDraft">
            云端同步
          </el-button>
        </div>

        <p class="permission-note">
          浏览器需要你点击按钮后才允许读取或写入系统剪切板。
        </p>
      </section>

      <section class="clipboard-list">
        <div class="list-header">
          <div class="section-title">
            <h3>云端记录</h3>
            <span>{{ filteredItems.length }} / {{ items.length }}</span>
          </div>
          <el-input
            v-model.trim="keyword"
            class="search-input"
            prefix-icon="el-icon-search"
            placeholder="搜索内容"
            clearable
          ></el-input>
        </div>

        <el-empty v-if="!loading && filteredItems.length === 0" description="暂无云端剪切板记录"></el-empty>

        <div v-else v-loading="loading" class="items">
          <article
            v-for="item in filteredItems"
            :key="item.id"
            class="clipboard-item"
            :class="{ selected: selectedItemId === item.id }"
            tabindex="0"
            @click="selectItem(item.id)"
            @keyup.enter="selectItem(item.id)"
            @keyup.space.prevent="selectItem(item.id)"
          >
            <div class="item-main">
              <div class="item-rail">
                <div class="item-badge">
                  <i class="el-icon-connection"></i>
                </div>
                <div v-if="selectedItemId === item.id" class="item-actions" @click.stop>
                  <el-tooltip content="复制到系统剪切板" placement="right">
                    <el-button icon="el-icon-document-copy" circle size="mini" @click="copyText(item.content)"></el-button>
                  </el-tooltip>
                  <el-tooltip content="填入编辑框" placement="right">
                    <el-button icon="el-icon-edit-outline" circle size="mini" @click="draft = item.content"></el-button>
                  </el-tooltip>
                  <el-tooltip content="取消云端同步" placement="right">
                    <el-button
                      icon="el-icon-delete"
                      circle
                      size="mini"
                      type="danger"
                      @click="confirmDelete(item)"
                    ></el-button>
                  </el-tooltip>
                </div>
              </div>
              <div class="item-content">
                <pre>{{ item.content }}</pre>
                <span>{{ formatDate(item.created_at) }}</span>
              </div>
            </div>
          </article>
        </div>
      </section>
    </div>
  </section>
</template>

<script>
import {
  createClipboardItem,
  deleteClipboardItem,
  listClipboardItems,
} from '@/api/clipboardSync';
import { formatDate } from '@/utils/file';

export default {
  name: 'CloudClipboard',
  data() {
    return {
      loading: false,
      syncing: false,
      draft: '',
      keyword: '',
      items: [],
      selectedItemId: null,
    };
  },
  computed: {
    filteredItems() {
      const keyword = this.keyword.toLowerCase();
      if (!keyword) return this.items;

      return this.items.filter((item) => item.content.toLowerCase().includes(keyword));
    },
  },
  mounted() {
    this.refresh();
  },
  methods: {
    formatDate,
    async refresh() {
      this.loading = true;
      try {
        const data = await listClipboardItems();
        this.items = data.items || [];
        if (!this.items.some((item) => item.id === this.selectedItemId)) {
          this.selectedItemId = null;
        }
      } catch (error) {
        this.$message.error(error.message || '云端剪切板加载失败');
      } finally {
        this.loading = false;
      }
    },
    selectItem(itemId) {
      this.selectedItemId = itemId;
    },
    async readClipboard() {
      if (!navigator.clipboard || !navigator.clipboard.readText) {
        this.$message.warning('当前浏览器不支持读取剪切板，请手动粘贴');
        return;
      }

      try {
        const text = await navigator.clipboard.readText();
        if (!text.trim()) {
          this.$message.warning('系统剪切板中没有文本内容');
          return;
        }
        this.draft = text;
        this.$message.success('已读取剪切板文本');
      } catch (error) {
        this.$message.warning('读取剪切板被浏览器拦截，请手动粘贴');
      }
    },
    async copyText(text) {
      if (!navigator.clipboard || !navigator.clipboard.writeText) {
        this.$message.warning('当前浏览器不支持写入剪切板');
        return;
      }

      try {
        await navigator.clipboard.writeText(text);
        this.$message.success('已复制到剪切板');
      } catch (error) {
        this.$message.warning('复制失败，请手动选择文本复制');
      }
    },
    async syncDraft() {
      const content = this.draft;
      if (!content.trim()) {
        this.$message.warning('请输入要同步的文本');
        return;
      }

      this.syncing = true;
      try {
        const result = await createClipboardItem(content);
        await this.refresh();
        this.$message.success(result.message === 'already synced' ? '云端已有相同内容' : '已同步到云端');
      } catch (error) {
        this.$message.error(error.message || '同步失败');
      } finally {
        this.syncing = false;
      }
    },
    async confirmDelete(item) {
      try {
        await this.$confirm('确定取消这条内容的云端同步吗？', '删除确认', {
          type: 'warning',
        });
        await deleteClipboardItem(item.id);
        this.$message.success('已取消云端同步');
        await this.refresh();
      } catch (error) {
        if (error !== 'cancel') {
          this.$message.error(error.message || '删除失败');
        }
      }
    },
  },
};
</script>

