<template>
  <main class="auth-page">
    <section class="auth-card">
      <div class="auth-copy">
        <h1>UniFileHub</h1>
        <p>登录后管理用户资料和个人云盘文件。</p>
      </div>

      <el-tabs v-model="activeTab" stretch>
        <el-tab-pane label="登录" name="login">
          <el-form ref="loginForm" :model="loginForm" :rules="loginRules" label-position="top">
            <el-form-item label="用户名" prop="username">
              <el-input v-model.trim="loginForm.username" prefix-icon="el-icon-user"></el-input>
            </el-form-item>
            <el-form-item label="密码" prop="password">
              <el-input
                v-model="loginForm.password"
                prefix-icon="el-icon-lock"
                show-password
                @keyup.enter.native="submitLogin"
              ></el-input>
            </el-form-item>
            <el-button class="full-button" type="primary" :loading="loading" @click="submitLogin">
              <i class="el-icon-right"></i>
              登录
            </el-button>
          </el-form>
        </el-tab-pane>

        <el-tab-pane label="注册" name="register">
          <el-form
            ref="registerForm"
            :model="registerForm"
            :rules="registerRules"
            label-position="top"
          >
            <el-form-item label="头像">
              <div class="avatar-row">
                <img v-if="avatarPreview" class="avatar-preview" :src="avatarPreview" alt="avatar" />
                <div v-else class="avatar-placeholder">
                  {{ registerForm.username.slice(0, 1).toUpperCase() || 'U' }}
                </div>
                <el-upload
                  action="#"
                  :auto-upload="false"
                  :show-file-list="false"
                  accept="image/*"
                  :on-change="handleAvatarChange"
                >
                  <el-button size="small">
                    <i class="el-icon-picture-outline"></i>
                    选择头像
                  </el-button>
                </el-upload>
              </div>
            </el-form-item>
            <el-form-item label="用户名" prop="username">
              <el-input v-model.trim="registerForm.username" prefix-icon="el-icon-user"></el-input>
            </el-form-item>
            <el-form-item label="密码" prop="password">
              <el-input v-model="registerForm.password" prefix-icon="el-icon-lock" show-password></el-input>
            </el-form-item>
            <el-form-item label="确认密码" prop="confirmPassword">
              <el-input
                v-model="registerForm.confirmPassword"
                prefix-icon="el-icon-lock"
                show-password
                @keyup.enter.native="submitRegister"
              ></el-input>
            </el-form-item>
            <el-button class="full-button" type="primary" :loading="loading" @click="submitRegister">
              <i class="el-icon-plus"></i>
              创建账号
            </el-button>
          </el-form>
        </el-tab-pane>
      </el-tabs>
    </section>
  </main>
</template>

<script>
import { login, register } from '@/api/userInfo';
import { createDefaultAvatar, fileToBase64 } from '@/utils/avatar';
import { setSession } from '@/utils/session';

export default {
  name: 'AuthPanel',
  data() {
    const checkPassword = (rule, value, callback) => {
      if (value !== this.registerForm.password) {
        callback(new Error('两次输入的密码不一致'));
        return;
      }
      callback();
    };

    return {
      activeTab: 'login',
      loading: false,
      avatarBase64: '',
      avatarPreview: '',
      loginForm: {
        username: '',
        password: '',
      },
      registerForm: {
        username: '',
        password: '',
        confirmPassword: '',
      },
      loginRules: {
        username: [{ required: true, message: '请输入用户名', trigger: 'blur' }],
        password: [{ required: true, message: '请输入密码', trigger: 'blur' }],
      },
      registerRules: {
        username: [
          { required: true, message: '请输入用户名', trigger: 'blur' },
          { min: 1, max: 10, message: '用户名最多 10 个字符', trigger: 'blur' },
        ],
        password: [{ required: true, message: '请输入密码', trigger: 'blur' }],
        confirmPassword: [{ validator: checkPassword, trigger: 'blur' }],
      },
    };
  },
  methods: {
    async handleAvatarChange(file) {
      this.avatarBase64 = await fileToBase64(file.raw);
      this.avatarPreview = URL.createObjectURL(file.raw);
    },
    async submitLogin() {
      this.$refs.loginForm.validate(async (valid) => {
        if (!valid) return;

        this.loading = true;
        try {
          const data = await login(this.loginForm);
          const session = {
            username: data.username,
            avatar_url: data.avatar_url,
            access_token: data.access_token,
            refresh_token: data.refresh_token,
          };
          setSession(session);
          this.$emit('authenticated', session);
          this.$message.success('登录成功');
        } catch (error) {
          this.$message.error(error.message || '登录失败');
        } finally {
          this.loading = false;
        }
      });
    },
    async submitRegister() {
      this.$refs.registerForm.validate(async (valid) => {
        if (!valid) return;

        this.loading = true;
        try {
          const avatar = this.avatarBase64 || createDefaultAvatar(this.registerForm.username);
          await register({
            username: this.registerForm.username,
            password: this.registerForm.password,
            avatar,
          });
          this.loginForm.username = this.registerForm.username;
          this.loginForm.password = this.registerForm.password;
          this.activeTab = 'login';
          await this.submitLogin();
        } catch (error) {
          this.$message.error(error.message || '注册失败');
        } finally {
          this.loading = false;
        }
      });
    },
  },
};
</script>

